# name: ends_with_repeat_choice
# description: Among pairs where exactly one sequence ends with a repeat (last two flips equal), the rate of choosing that sequence; observed < null means people penalise a terminal repetition (recency/gambler's-fallacy salience) more than the model's position-blind features predict.
def test_statistic(df):
    a = df["sequence_a"]; b = df["sequence_b"]
    ra = (a.str[-1] == a.str[-2]).values; rb = (b.str[-1] == b.str[-2]).values
    m = ra != rb
    if m.sum() == 0:
        return 0.5
    ch = np.where(ra, df["chose_left"].values, 1 - df["chose_left"].values)
    return float(ch[m].mean())

# name: shorter_longest_run_choice
# description: Among pairs whose longest runs differ, the rate of choosing the sequence with the shorter longest run; observed > null means people penalise long streaks more than the balance/alternation features predict (observed < null: less).
def test_statistic(df):
    def lr(s):
        best = cur = 1
        for i in range(1, len(s)):
            cur = cur + 1 if s[i] == s[i-1] else 1
            best = max(best, cur)
        return best
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    d = {s: lr(s) for s in u}
    ra = df["sequence_a"].map(d).values; rb = df["sequence_b"].map(d).values
    m = ra != rb
    if m.sum() == 0:
        return 0.5
    ch = np.where(ra < rb, df["chose_left"].values, 1 - df["chose_left"].values)
    return float(ch[m].mean())

# name: balanced_pairs_more_alternation_choice
# description: Among pairs whose head counts differ by at most one but different numbers of alternations, the rate of choosing the sequence with more alternations; observed > null means people favour alternation (when balance is nearly tied) more than the model's alternation term predicts.
def test_statistic(df):
    def alts(s):
        return sum(s[i] != s[i-1] for i in range(1, len(s)))
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    d = {s: alts(s) for s in u}
    aa = df["sequence_a"].map(d).values; ab = df["sequence_b"].map(d).values
    ha = df["sequence_a"].str.count("H").values; hb = df["sequence_b"].str.count("H").values
    m = (np.abs(ha - hb) <= 1) & (aa != ab)
    if m.sum() == 0:
        return 0.5
    ch = np.where(aa > ab, df["chose_left"].values, 1 - df["chose_left"].values)
    return float(ch[m].mean())

# name: participant_left_rate_sd
# description: Across-participant SD of each person's left-choice rate; observed > null means individual side biases vary more than the model's single shared side_bias allows.
def test_statistic(df):
    return float(df.groupby("participant_id")["chose_left"].mean().std())

# name: more_distinct_triplets_choice
# description: Among pairs whose number of distinct length-3 substrings differs, the rate of choosing the sequence with more distinct triplets (motif diversity); observed > null means people reward pattern diversity more than the model predicts.
def test_statistic(df):
    def nd(s):
        return len({s[i:i+3] for i in range(len(s) - 2)})
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    d = {s: nd(s) for s in u}
    ra = df["sequence_a"].map(d).values; rb = df["sequence_b"].map(d).values
    m = ra != rb
    if m.sum() == 0:
        return 0.5
    ch = np.where(ra > rb, df["chose_left"].values, 1 - df["chose_left"].values)
    return float(ch[m].mean())
